// === Tab: mySketch.js ===
/* let processing.*/

let typeA=0;
let typeB=0;

let numTypes;
let colorStep;
let numParticles = 1000;
ArrayList<Particle> swarm;

float [][] forces;
float [][] minDistances;
float [][] radii;

let K = 0.05;
let friction = 1-0.15;
let pcentRepultion = 20;
let fonction = 0;
let valeur=0;

let deplacement;
/*************************************************************/
function setup() {
  //createCanvas(750, 500);
	createCanvas(windowWidth, windowHeight, WEBGL);
  colorMode(HSB, 360, 100, 100);
  noStroke();

	numTypes = int(random(2, 6));
  colorStep = 360 / numTypes;

  swarm = new ArrayList<Particle>();
  for (i = 0; i < numParticles; i++) {
    swarm.add(new Particle());
  }
  forces = new float [numTypes][numTypes];
  minDistances = new float [numTypes][numTypes];
  radii = new float [numTypes][numTypes];
  setParameters();
}

/*********************************
 *             let R let W           *
 *********************************/
function draw() {
  background(0);

	deplacement = new PVector(0, 0);
  for (let p of swarm) {
    p.update();
    p.display();
  }
	//drawForces();
	drawDatas();
	strokeWeight(2);stroke(255);line( width/2, height/2 ,width/2+deplacement.x, height/2+deplacement.y );noStroke();
}

function drawDatas(){
	let x,y,l,ts;
	x=100;
	y=20;
	ts=20;
	l=1;
	//push();
	fill(typeA * colorStep, 100, 100);ellipse(x,   y+l*ts,20,20);
	fill(typeB * colorStep, 100, 100);ellipse(x+80,y+l*ts,20,20);
  l++;
	textAlign(LEFT,TOP);fill(255);text("typeA="+typeA+" typeB="+typeB, x, y+l*ts);
  l++;
	text("[F] - force = "+forces[typeA][typeB], x, y+l*ts);
	strokeWeight(2);stroke(255);	line( x, y+l*ts, x+int(forces[typeA][typeB]*100), y+l*ts);	noStroke();
	fill(255);
  l++;
	text("[R] - radii = "+int(radii[typeA][typeB]), x, y+l*ts);
	strokeWeight(2);stroke(255);	line( x, y+l*ts, x+int(radii[typeA][typeB]), y+l*ts);	noStroke();
  l++;
	text("[D] - minDistances = "+int(minDistances[typeA][typeB]), x, y+l*ts);
	strokeWeight(2);stroke(255);	line( x, y+l*ts, x+int(minDistances[typeA][typeB]), y+l++*ts);	noStroke();

	text("[K] - K="+K,x, y+l*ts); l++;
	text("[L] - friction="+friction,x, y+l*ts); l++;
	text("[M] - Repultion="+pcentRepultion+"%",x, y+l*ts); l++;

	drawForces();
}

/*************************************************************/
function drawForces(){	
	var x,y,l,ts;
	x=10;
	y=20;
	ts=30;
	l=6;
	/*textAlign( CENTER, CENTER);*/	
	fill(360);
	switch(fonction) {
		case 0: // forces
			text("forces",x,y+l*ts);
			break;
		case 1: // radii
			text("radii",x,y+l*ts);
			break;
		case 2: // minDistances
			text("minDistances",x,y+l*ts);
			break;
	}
	l++;
	fill(360);noStroke();
	rect( x + 30 +(typeB*ts), y+(typeA+l+1)*ts, ts,15);
	//noStroke();

	for( i=0 ; i<numTypes; i++){
		fill(i * colorStep, 100, 100);
		text(i, x+30+i*ts, y+l*ts);
		text(i, x     ,y+(l+i+1)*ts);
		fill(360);
		for( j=0 ; j<numTypes; j++){
			switch(fonction){
				case 0:
					forces[i][j]<0?fill(0,100,100):fill(270,100,100);
					//fill(360*(forces[i][j]>0));
					text(forces[i][j], x +30 + (j*ts), y+(l+i+1)*ts);
					break;
				case 1:
					fill(270,100,100);
					text( int(radii[i][j]), x +30 + (j*ts), y+(l+i+1)*ts);
					break;
				case 2:
					fill(270,100,100);
					text( int(minDistances[i][j]), x +30 + (j*ts), y+(l+i+1)*ts);
					break;
			}
		}
	}
	l+=numTypes+1;
 	fill(360);noStroke();
	text("valeur = "+valeur,x,y+l*ts);
//	noStroke();
}

/**************************\
        	I.O.
\**************************/
function mousePressed(){
//  setParameters();
}
/*************************************************************/
function mouseWheel(event) {
  let e = event.getCount();
 	forces[typeA][typeB]=forces[typeA][typeB]+1;
	exit();
}
/*************************************************************/
function keyReleased() {
	if(key==CODED){
		switch (keyCode) {
			case UP://UP_ARROW:
				typeA=(typeA+numTypes-1)%numTypes;
				break;
			case DOWN://UP_ARROW:
				typeA=(typeA+1)%numTypes;
				break;
			case LEFT://UP_ARROW:
				typeB=(typeB+numTypes-1)%numTypes;
				break;
			case RIGHT://UP_ARROW:
				typeB=(typeB+1)%numTypes;
				break;
			case HOME://HOME:
				typeA=0;
				typeB=0;
				break;
			case END://END:
				typeA=numTypes-1;
				typeB=numTypes-1;
				break;
			default:
				text("key="+key+" keycode="+keyCode, 1500, 50);
		}
	}else{
		switch (key) {
			case ' ':
				setParameters();
				break;
			case 'f':	// let case 'F':
				fonction=0;
				break;
			case 'r':	// let case 'R':
			case 114:
				fonction=1;
				break;
			case 'd':	// minDistances
			case 'D':
				fonction=2;
				break;
			case '0':
			case '1':
			case '2':
			case '3':
			case '4':
			case '5':
			case '6':
			case '7':
			case '8':
			case '9':
				switch (fonction){
					case 0:	// forces
						forces[typeA][typeB] = (key-48)/10;
						break;
					case 1:	// let radii[typeA][typeB] = (key-48)*100;
						break;
					case 2:	// minDistances
						minDistances[typeA][typeB] = (key-48)*100;
						break;
				}
				//forces[typeA][typeB] = (key-48)/10;
				break;
			case '-': 
				forces[typeA][typeB]=-abs(forces[typeA][typeB]);
				break;
			case '+':
				forces[typeA][typeB]=abs(forces[typeA][typeB]);
				break;
			case char(10): // entrée
				//forces[typeA][typeB]=valeur/1000;
				break;
			default:
				// let the last key pressed and its code.
				text("key="+key+" keycode="+keyCode, 1500, 50);
		}
	}
}



/*************************************************************/
function setParameters() {
  for (i = 0; i < numTypes; i++) {
    for (j = 0; j < numTypes; j++) {
      forces[i ][j ] = int(random(0.3, 1.0)*10)/10;
      if (random(100)<pcentRepultion) {
        forces[i][j]*=-1;
      }
      minDistances[i][j]=random(30, 50);
      radii[i][j]=random(70, 250);
    }
  }
}


/*************************************************************/
class Particle {

  position;
  velocity;
  type;

  constructor() {
		let rad = random(100);
		let ang = random(TWO_PI);
		position = new PVector(rad * cos(ang) + width/2, rad * sin(ang)+height/2);
    velocity = new PVector(0, 0);
    type = int(random(numTypes));
  }

  function update() {
    let direction = new PVector(0, 0);
    let totalForce = new PVector(0, 0);
    let acceleration = new PVector(0, 0);
    let distance;
    for (let p of swarm) {
      if (p != this) {
   //     direction.mult(0); ligne inutile étant donné la ligne ci-dessous
        direction = new PVector(p.position.x, p.position.y);
        direction.sub(position);
        if (direction.x>0.5*width) {
          direction.x-=width;
        }
        if (direction.x<-0.5*width) {
          direction.x+=width;
        }
        if (direction.y>0.5*height) {
          direction.y-=height;
        }
        if (direction.y<-0.5*height) {
          direction.y+=height;
        }

        distance = direction.mag();
        direction.normalize();
        if (distance < minDistances[type][p.type]) {
          let force = new PVector(direction.x, direction.y);
          force.mult(abs(forces[type][p.type]) * (-3));
          force.mult(map(distance, 0, minDistances[type][p.type], 1, 0));
          force.mult(K);
          totalForce.add(force);
        }
        if(distance < radii[type][p.type]){
        var force = new PVector(direction.x, direction.y);
          force.mult(forces[type][p.type]);
          force.mult(map(distance, 0, radii[type][p.type], 1, 0));
          force.mult(K);
          totalForce.add(force);
        }

      }
    }

    acceleration.add(totalForce);
    velocity.add(acceleration);
    position.add(velocity);
    deplacement.add(velocity);
    position.x = (position.x+width)%width;
    position.y = (position.y+height)%height;
    velocity.mult(friction);
  }



  function display() {
		let r=10;
    fill(this.type * colorStep, 100, 100);
    ellipse(this.position.x, this.position.y, r,  r);
  }
}

